SINA_SMART["physio1-ecg"] = {"lecture":"physio1-ecg","title":"Electrocardiography (ECG)","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"physio1-ecg:e0","text":"Nodal tissue conducts; myocardium contracts.","topic":"Cardiac electrophysiology","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-ecg:e1","text":"Myocardial AP: phase 0 Na⁺ in, 2 plateau, 3 K⁺ out, 4 rest (−90 mV).","topic":"Cardiac electrophysiology","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-ecg:e3","text":"25 mm/s (1 mm = 0.04 s); 10 mm/mV.","topic":"Cardiac electrophysiology","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-ecg:e6","text":"P = atria; PR 0.12-0.20 s; QRS = ventricles; T = ventricular repolarisation; QT 0.35-0.44 s.","topic":"Cardiac electrophysiology","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-ecg:e2","text":"Heart = dipole; electrode facing an approaching front → positive deflection.","topic":"Physical basis: the heart as a dipole","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-ecg:e4","text":"Limb leads: DI, DII, DIII (Einthoven; DII = DI + DIII), aVR, aVL, aVF.","topic":"Recording: 12 leads","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-ecg:e5","text":"V1/V2: 4th space at the sternum; V4: 5th space midclavicular; V6: mid-axillary.","topic":"Recording: 12 leads","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-ecg:e7","text":"Normal rate 60-100; axis 0 to +90°.","topic":"Reading an ECG","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-ecg:e8","text":"PR > 0.20 s: first-degree AV block; necrotic Q: old infarct; ST elevation: ischaemia.","topic":"Reading an ECG","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-ecg:e9","text":"Territories: inferior DII/DIII/aVF; anteroseptal V1-V3; lateral DI/aVL/V5/V6.","topic":"Reading an ECG","sec":3,"importance":"core","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"14fkr9w":"a","jlmp5l":"a","5ds31p":"a","8rovr7":"a","uy18g5":"a","78wtdc":"a","170xst0":"a","16j2b0u":"a","ttthpx":"a","149guii":"a","1trqmij":"a","dkjqrp":"a","1uq9w9x":"a","hb9ivi":"a","auyzm5":"x"},"mapCounts":{"verified":0,"auto":14,"ambiguous":0,"missing":1},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"physio1-ecg:e0":{"s":0,"u":["Nodal tissue conducts; myocardium contracts.","Two tissues: nodal tissue (SA node, AV node, bundle of His and branches, Purkinje fibres), which generates and conducts the impulse, and myocardium , which contracts."],"dp":[]},"physio1-ecg:e1":{"s":0,"u":["Myocardial AP: phase 0 Na⁺ in, 2 plateau, 3 K⁺ out, 4 rest (−90 mV).","The action potential of a myocardial cell: phase 0 fast depolarisation to about +30 mV (Na⁺ entry); phase 1 early repolarisation; phase 2 plateau (Ca²⁺ entry balancing K⁺ exit); phase 3 repolarisation (K⁺ exit); phase 4 resting potential.","At rest the membrane is polarised (inside negative, about −90 mV in myocardial cells)."],"dp":[]},"physio1-ecg:e3":{"s":0,"u":["25 mm/s (1 mm = 0.04 s); 10 mm/mV."],"dp":[]},"physio1-ecg:e6":{"s":0,"u":["P = atria; PR 0.12-0.20 s; QRS = ventricles; T = ventricular repolarisation; QT 0.35-0.44 s.","The impulse starts in the SA node, spreads through both atria, converges on the AV node, then descends the His bundle and Purkinje fibres to the apex and both ventricles simultaneously."],"dp":[]},"physio1-ecg:e2":{"s":1,"u":["Heart = dipole; electrode facing an approaching front → positive deflection.","Seen from distant electrodes, the heart behaves like an electric dipole .","Rule: an electrode that sees depolarisation coming records a positive deflection; one that sees it moving away records a negative deflection ."],"dp":[]},"physio1-ecg:e4":{"s":2,"u":["Limb leads: DI, DII, DIII (Einthoven; DII = DI + DIII), aVR, aVL, aVF.","Frontal (limb) leads : augmented unipolar aVR (red, right wrist), aVL (yellow, left wrist), aVF (green, left ankle), black on the right ankle as ground; bipolar Einthoven leads DI (right arm-left arm), DII (right arm-left leg), DIII (left arm-left leg), with DII = DI + DIII ."],"dp":[]},"physio1-ecg:e5":{"s":2,"u":["V1/V2: 4th space at the sternum; V4: 5th space midclavicular; V6: mid-axillary.","Precordial leads (horizontal plane): V1 4th right intercostal space at the sternal edge; V2 4th left intercostal space at the sternal edge; V4 5th left space, midclavicular line; V3 between V2 and V4; V5 anterior axillary line; V6 mid-axillary line (same level as V4)."],"dp":[]},"physio1-ecg:e7":{"s":3,"u":["Normal rate 60-100; axis 0 to +90°.","Rate : 60-100/min; &gt; 100 tachycardia, &lt; 60 bradycardia (normal in athletes)."],"dp":[{"h":"Counting the rate in five seconds","t":"At 25 mm/s, one large square (5 mm) lasts 0.2 s, so 300 large squares fill a minute. The heart rate is therefore 300 divided by the number of large squares between two R waves : one square = 300/min, two = 150, three = 100, four = 75, five = 60, six = 50. Memorising '300-150-100-75-60-50' gives an instant rate estimate for regular rhythms; for irregular rhythms such as atrial fibrillation, count the QRS complexes in 10 seconds (a standard strip) and multiply by 6. Source: the lecture's paper speed (1 mm = 0.04 s) and normal rate range."}]},"physio1-ecg:e8":{"s":3,"u":["PR > 0.20 s: first-degree AV block; necrotic Q: old infarct; ST elevation: ischaemia.","PR 0.12-0.20 s (&gt; 0.20 s: first-degree AV block).","Q wave normal if &lt; 0.04 s and &lt; 1/3 of R; a wider, deeper Q in several leads is a necrotic Q wave (old infarct)."],"dp":[]},"physio1-ecg:e9":{"s":3,"u":["Territories: inferior DII/DIII/aVF; anteroseptal V1-V3; lateral DI/aVL/V5/V6.","Territories : DII, DIII, aVF inferior; V1-V3 anteroseptal; V1-V5 anterior; V3-V4 apical; DI, aVL, V5, V6 lateral."],"dp":[]}},"meta":{"14fkr9w":{"a":"recall","vg":"physio1-ecg:e8/recall/1"},"jlmp5l":{"a":"recall","vg":"physio1-ecg:e6/recall/1"},"5ds31p":{"a":"recall","vg":"physio1-ecg:e6/recall/1"},"8rovr7":{"a":"recall","vg":"physio1-ecg:e7/recall/1"},"uy18g5":{"a":"recall","vg":"physio1-ecg:e8/recall/2"},"78wtdc":{"a":"relationship","vg":"physio1-ecg:e4/relationship/1"},"170xst0":{"a":"relationship","vg":"physio1-ecg:e4/relationship/2"},"16j2b0u":{"a":"recall","vg":"physio1-ecg:e5/recall/1"},"ttthpx":{"a":"recall","vg":"physio1-ecg:e2/recall/1"},"149guii":{"a":"relationship","vg":"physio1-ecg:e1/relationship/1"},"1trqmij":{"a":"recall","vg":"physio1-ecg:e1/recall/1"},"dkjqrp":{"a":"recall","vg":"physio1-ecg:e7/recall/2"},"1uq9w9x":{"a":"recall","vg":"physio1-ecg:e9/recall/1"},"hb9ivi":{"a":"recall","vg":"physio1-ecg:e8/recall/3"}},"explRev":"e9157d8b4069"};
